import {
  Box,
  Typography,
  Container,
  IconButton,
} from "@mui/material";


export default function Footer() {

  return (

    <Box
      sx={{
        mt: 10,
        py: 6,
        background:
          "linear-gradient(to right, #0f172a, #1e293b)",
        color: "white",
      }}
    >

      <Container maxWidth="lg">

        <Box
          sx={{
            display: "flex",
            justifyContent:
              "space-between",
            alignItems: "center",
            flexWrap: "wrap",
            gap: 3,
          }}
        >

          <Box>

            <Typography
              variant="h4"
              fontWeight={800}
              gutterBottom
            >
              DevBlog
            </Typography>

            <Typography
              variant="body1"
              sx={{
                opacity: 0.75,
                maxWidth: 400,
                lineHeight: 1.8,
              }}
            >
              A modern blogging platform
              built using MERN Stack and
              Material UI.
            </Typography>

          </Box>

          

        </Box>

        <Box
          sx={{
            borderTop:
              "1px solid rgba(255,255,255,0.1)",
            mt: 5,
            pt: 3,
            textAlign: "center",
          }}
        >

          <Typography
            variant="body2"
            sx={{ opacity: 0.6 }}
          >
            © {new Date().getFullYear()}
            {" "}
            DevBlog. All rights reserved.
          </Typography>

        </Box>

      </Container>

    </Box>
  );
}
